// `ggml_argsort`'s DESC arm uses — reproduced without materialising the
// other 502 ranks, and L5a-1's fixture says what it has to hit: the
// reference's selection **set for set on all 4096 tokens**, with the one row
// whose order differs being a pair 4.35e-07 apart.

#include "llm_common.glsl"

#define WG 256
#define MAX_EXPERTS 512
#define MAX_USED 16

layout(local_size_x = WG) in;

// The probabilities, cached for the ten selection passes and overwritten with
// -1 as each is taken. 2 KB, against re-reading the row ten times.
shared float probs[MAX_EXPERTS];
shared float shVal[WG / 64];
shared uint shIdx[WG / 64];
shared float shSel[MAX_USED];
shared uint shSelIdx[MAX_USED];

void main() {
    uint t = gl_WorkGroupID.x;
    uint tid = gl_LocalInvocationID.x;
    if (t >= pc.tokens) {
        return;
    }
    uint nE = pc.gemmK;          // the expert count: the reduction extent here
    uint used = MOE_USED;
    uint base = pc.qkvOff + t * pc.gemmN;
    uint sg = tid / 64u;

    // ---- ggml_soft_max over the 512 logits: the max subtracted for range,
    // then exp and a normalise.
    float m = -1.0 / 0.0;
    for (uint i = tid; i < nE; i += WG) {
        float v = act[base + i];
        probs[i] = v;
        m = max(m, v);
    }
    m = subgroupMax(m);
    if (subgroupElect()) {
        shVal[sg] = m;
    }
    barrier();
    [[unroll]] for (uint w = 0u; w < WG / 64u; ++w) {
        m = max(m, shVal[w]);
    }
    barrier();

    float s = 0.0;
    for (uint i = tid; i < nE; i += WG) {
        float e = exp(probs[i] - m);
        probs[i] = e;
        s += e;
    }
    s = subgroupAdd(s);
    if (subgroupElect()) {
        shVal[sg] = s;
    }
    barrier();
    s = 0.0;
    [[unroll]] for (uint w = 0u; w < WG / 64u; ++w) {
        s += shVal[w];
    }
    float inv = 1.0 / s;
    for (uint i = tid; i < nE; i += WG) {
        probs[i] *= inv;
    }
    barrier();

    // ---- The top `used`, one workgroup argmax at a time. A taken expert is
    // marked with -1, which no probability can reach, so the mask costs a
    // store rather than a second array.
    for (uint k = 0u; k < used; ++k) {
        float bv = -1.0;
        uint bi = 0xFFFFFFFFu;
        for (uint i = tid; i < nE; i += WG) {
            float v = probs[i];
            if (v > bv) {
                bv = v;
                bi = i;
            }
        }
        float wv = subgroupMax(bv);
        // The tie rule is the comparator's: `>` is false between equals, so a
        // stable sort leaves them in ascending index order and the lowest
        // index wins.
        uint wi = subgroupMin(bv == wv ? bi : 0xFFFFFFFFu);
        if (subgroupElect()) {
            shVal[sg] = wv;
            shIdx[sg] = wi;
        }
        barrier();
        float best = shVal[0];
        uint bestI = shIdx[0];
        [[unroll]] for (uint w = 1u; w < WG / 64u; ++w) {
            if (shVal[w] > best || (shVal[w] == best && shIdx[w] < bestI)) {
                best = shVal[w];
                bestI = shIdx[w];
            }
        }
        if (tid == 0u) {
            shSel[k] = best;
            shSelIdx[k] = bestI;
        }
        barrier();
        if (tid == 0u) {
            probs[bestI] = -1.0;
        }
        barrier();
    }

    // ---- The ten weights, `norm_w` and the reference's own clamp, then the
    // shared expert's gate in the last slot. Serial on one lane because
    // `used` is ten: a reduction over ten values costs more in barriers than
    // it saves.
    if (tid == 0u) {
        float sum = 0.0;
        [[unroll]] for (uint k = 0u; k < MAX_USED; ++k) {
            if (k < used) {
                sum += shSel[k];
            }
        }
        // ggml_clamp(weights_sum, 6.103515625e-5, INFINITY) — the smallest
        // normal half, the reference's guard against a zero denominator. L5a
        // measured it to be the identity on all 4096 rows of the 4 k dump
        // (the smallest sum there is 0.0554) and it is reproduced anyway,
        // because it is in the graph.
        sum = max(sum, 6.103515625e-5);
        uint slots = used + 1u;
        uint topk = pc.moeWeightOff + pc.tokens * slots;
        for (uint k = 0u; k < used; ++k) {
            actu[topk + t * used + k] = shSelIdx[k];
            act[pc.moeWeightOff + t * slots + k] = shSel[k] / sum;
        }
        // The shared expert runs for every token and its weight is the
        // sigmoid of the fused matrix's 513th column.
        float g = act[base + nE];
        act[pc.moeWeightOff + t * slots + used] = 1.0 / (1.0 + exp(-g));
    }
}
===== PERM
#version 450

#extension GL_KHR_shader_subgroup_basic : require
#extension GL_KHR_shader_subgroup_arithmetic : require
#extension GL_EXT_shader_16bit_storage : require
#extension GL_EXT_shader_explicit_arithmetic_types_float16 : require
#extension GL_EXT_control_flow_attributes : require

// The routing permutation and the tile schedule it implies (LLM.md L5b).
//
// A counting sort over the 512 experts: histogram, exclusive prefix sum,
// scatter. It is one workgroup because the whole input is `tokens * used`
// integers — 5120 at a 512-token ubatch, 40 960 at the 4 k fixture — and 97%
// of this block's time is in the two GEMMs behind it.
//
// **L5a-4 is why the schedule is a list and not a grid.** At a 512-token
// ubatch only **274 of 512 experts are touched**, one of them takes **484 of
// the 512 tokens** and the other 273 have fewer than 19: a workgroup per
// expert has a 26x load imbalance and a grid of (experts x fixed row blocks)
// is almost entirely empty. So this kernel emits one record per (expert, row
// block) that has rows — `tileCount` of them — and the GEMM dispatches a
// static upper bound of `ceil(tokens*used/BM) + nExperts` row blocks, every
// one past `tileCount` returning before it reads anything.
//
// **Each expert's rows are padded up to `pc.gemmN`, and that padding is what
// buys the GEMM its epilogue.** A cooperative-matrix store covers sixteen
// rows at once and cannot be masked, so a tile whose expert runs out of rows
// part-way through would have to stage its accumulators in LDS and copy them
// out under a bound — which is 8-16 KB of LDS on a kernel whose occupancy is
// already one wave a SIMD. Rounding every expert's range up instead means a
// tile's rows are *always* that expert's, the store goes straight out, and
// the padding rows are named by a **sentinel** permutation entry pointing at
// a token index one past the batch, whose activation row is zero. The
// alignment is the wider of the two modes' row blocks, so both tile lists
// divide it exactly and the two ladders stay independent. **Since §2.12 it
// is one fragment for the single-wave rungs** (KERNELS.md G5c): those are
// `SHORT` builds of the GEMM that bound their tiles by a record's real rows,
// so an expert's range is rounded to sixteen and its last block is short;
// `MoEGPU.pad` still widens the alignment to the block when a plan names a
// multi-wave rung.
//
// Two more things the layout does. The row a permutation entry names is
// `token * (used + 1) + slot`, not the token — so the slot stride carries the
// shared expert's row as its last element. And the **inverse** permutation is
// written beside it, because the down projection's output lands in
// permutation order and the combine has to find a token's eleven
// contributions again; the alternative is a scattered store, and a scattered
// store is the LDS round trip this file exists to avoid.
//
// The order of rows *within* an expert is whatever the scatter's atomics
// give, and nothing depends on it: every row is independent and the combine
// sums by (token, slot).

#include "llm_common.glsl"

#define WG 256
#define MAX_EXPERTS 512

layout(local_size_x = WG) in;

shared uint shCnt[MAX_EXPERTS];
shared uint shWave[WG / 64];
shared uint shTotal;

void main() {
    uint tid = gl_LocalInvocationID.x;
    uint nE = pc.gemmK;          // the expert count
    uint used = MOE_USED;
    uint slots = used + 1u;
    uint pairs = pc.tokens * used;
    uint bm = pc.gemmM;          // the row block this tile list is cut to
    uint pad = pc.gemmN;         // the row alignment both lists share
    uint sg = tid / 64u;

    // The shared expert is one group of the same grouped GEMM and it takes
    // the front of the row space: it runs for every token, so its rows are
    // the identity and the host writes them. The routed experts start behind
    // it.
    uint reserve = ((pc.tokens + pad - 1u) / pad) * pad;

    // The four per-expert arrays the counting sort keeps. They sit behind the
    // permutation, which the host sizes for the widest rung, so where they
    // start is the host's to say — `moeBOff2`, which in a GEMM dispatch is
    // the second quantised matrix and here has no matrix to name.
    uint book = pc.moeBOff2;
    uint counts = book;
    uint offsets = book + nE;
    uint cursor = book + 2u * nE;
    uint tileBase = book + 3u * nE;
    uint topk = pc.moeWeightOff + pc.tokens * slots;
    uint invPerm = topk + pairs;

    for (uint e = tid; e < nE; e += WG) {
        actu[counts + e] = 0u;
    }
    barrier();

    // ---- The histogram.
    for (uint p = tid; p < pairs; p += WG) {
        atomicAdd(actu[counts + actu[topk + p]], 1u);
    }
    barrier();

    // ---- Two exclusive prefix sums over the experts, in the same shape: one
    // over the padded counts, which is where an expert's rows start, and one
    // over padded/BM, which is where its tile records start. A subgroup scan
    // per wave, the wave totals carried across, and a carry across the
    // chunks — because nE is 512 and the workgroup is 256.
    uint carryRows = reserve;
    uint carryTiles = 0u;
    for (uint c0 = 0u; c0 < MAX_EXPERTS; c0 += WG) {
        uint e = c0 + tid;
        uint cnt = (e < nE) ? actu[counts + e] : 0u;
        shCnt[e] = cnt;
        uint padded = ((cnt + pad - 1u) / pad) * pad;
        // A whole number of blocks under an alignment at least the block;
        // a short last one under a narrower alignment (the SHORT rungs,
        // §2.12), bounded by the record's real rows.
        uint nt = (padded + bm - 1u) / bm;

        uint rowTot = subgroupAdd(padded);
        uint rowEx = subgroupExclusiveAdd(padded);
        uint tileTot = subgroupAdd(nt);
        uint tileEx = subgroupExclusiveAdd(nt);
        if (subgroupElect()) {
            shWave[sg] = rowTot;
        }
        barrier();
        uint rowBefore = 0u, rowAll = 0u;
        [[unroll]] for (uint w = 0u; w < WG / 64u; ++w) {
            rowAll += shWave[w];
            if (w < sg) {
                rowBefore += shWave[w];
            }
        }
        barrier();
        if (subgroupElect()) {
            shWave[sg] = tileTot;
        }
        barrier();
        uint tileBefore = 0u, tileAll = 0u;
        [[unroll]] for (uint w = 0u; w < WG / 64u; ++w) {
            tileAll += shWave[w];
            if (w < sg) {
                tileBefore += shWave[w];
            }
        }
        barrier();

        if (e < nE) {
            uint off = carryRows + rowBefore + rowEx;
            actu[offsets + e] = off;
            actu[cursor + e] = off;
            actu[tileBase + e] = carryTiles + tileBefore + tileEx;
        }
        carryRows += rowAll;
        carryTiles += tileAll;
    }
    if (tid == 0u) {
        actu[pc.moeTileOff] = carryTiles;
        actu[pc.moeTileOff + 1u] = carryRows;
        shTotal = carryRows;
    }
    barrier();

    // ---- Every routed row starts as the sentinel: a (token, slot) pair one
    // token past the batch, whose activation row is a zero pad. What the
    // scatter does not overwrite is padding, and padding has to compute
    // something finite rather than whatever the arena last held.
    // The fill runs on to a whole widest block past the end, because a
    // SHORT rung's last block stages every row of the block whether or not
    // it multiplies them (§2.12), and the arena has the room (`maxRows`).
    uint sentinel = pc.tokens * slots;
    uint fillEnd = ((shTotal + 63u) / 64u) * 64u;
    for (uint r = reserve + tid; r < fillEnd; r += WG) {
        actu[pc.moePermOff + r] = sentinel;
    }
    barrier();

    // ---- The scatter, and the inverse beside it. `p` is (token, slot)
    // flattened by `used`; what lands in the permutation is the same pair
    // flattened by `used + 1`, so the shared expert's slot is already spoken
    // for.
    for (uint p = tid; p < pairs; p += WG) {
        uint e = actu[topk + p];
        uint idx = atomicAdd(actu[cursor + e], 1u);
        uint tok = p / used;
        uint k = p - tok * used;
        actu[pc.moePermOff + idx] = tok * slots + k;
        actu[invPerm + tok * slots + k] = idx;
    }

    // ---- The tile records: expert, first row, and how many of the block's
    // rows are real. The range is padded to the block, so a block is always
    // whole; the third word is what lets the decode GEMV skip the padding
    // (llm_moe_gemv.comp, CONCURRENCY.md C5). The GEMM does not read it.
    for (uint e = tid; e < nE; e += WG) {
        uint cnt = shCnt[e];
        uint padded = ((cnt + pad - 1u) / pad) * pad;
        uint off = actu[offsets + e];
        uint tb = actu[tileBase + e];
        for (uint mb = 0u; mb * bm < padded; ++mb) {
            uint rec = pc.moeTileOff + 2u + 3u * (tb + mb);
            actu[rec] = e;
            actu[rec + 1u] = off + mb * bm;
            actu[rec + 2u] = (cnt > mb * bm) ? min(cnt - mb * bm, bm) : 0u;
        }
    }
}
===== COMBINE
#version 450

#extension GL_EXT_shader_16bit_storage : require
#extension GL_EXT_shader_explicit_arithmetic_types_float16 : require
#extension GL_EXT_control_flow_attributes : require

// `ffn_out` — the ten routed contributions and the shared expert's, weighted
// and summed (LLM.md L5b).
//
// It exists because the down projection cannot accumulate in place: a token's
// ten experts are ten different tiles of the grouped GEMM, so without a float
// atomic each writes its own row and something has to add them up.
//
// It carries the **routing weights** for a reason that is not about
// arithmetic. The down projection's rows come out in permutation order, which
// is what lets it store whole cooperative-matrix fragments straight to global
// instead of scattering them a row at a time through LDS; but in that order a
// workgroup does not know which (token, slot) a row is without reading the
// permutation per row, and the weight would have to be applied per row
// anyway. Here the weight is a scalar per row of a read that happens once
// regardless. So `ffn_moe_weighted` is still never a tensor, and the store it
// would have ridden on stays a fragment store.
//
// The order is the reference's: the ten in slot order, then
// `ffn_shexp_gated`, which is the chain of adds `build_layer_ffn` emits and
// the order `moe.go`'s CPU reference sums in.

#include "llm_common.glsl"

// **The grid is (column block, token) and it was (token)** — D11 again, and
// the cheapest instance of it in this block (L8d-2). At one token the whole
// dispatch was *one workgroup*: 2560 columns, eleven rows each, 112 KB of
// reads on a 40-CU device, 22 us at 6 GB/s. It is one line of arithmetic and
// no arithmetic changed.
//
// **The column block is the x axis and that is not cosmetic.** The obvious
// spelling puts the token there, and at a 2048-token ubatch it is **9.2x
// slower than the single workgroup it replaced**: this dispatch reads 230 MB
// out of a 566 MB arena, consecutive workgroups would then be consecutive
// *tokens* at the same 256-byte column slice, and the rows of one token's
// eleven contributions are 10 KB apart. With the column block fastest, the
// forty workgroups of one token walk its rows end to end and the block
// streams again — 34 GB/s back to 315 (L8d-2).
#define WG 64

layout(local_size_x = WG) in;

void main() {
    uint t = gl_WorkGroupID.y;
    uint j = gl_WorkGroupID.x * WG + gl_LocalInvocationID.x;
    if (t >= pc.tokens || j >= pc.nEmbd) {
        return;
    }
    uint slots = MOE_USED + 1u;
    // The inverse permutation sits behind the weights and the top-k, all
    // three indexed by the same (token, slot).
    uint invPerm = pc.moeWeightOff + pc.tokens * slots + pc.tokens * MOE_USED;
    float s = 0.0;
    for (uint k = 0u; k < slots; ++k) {
        uint row = actu[invPerm + t * slots + k];
        s += act[pc.gatedOff + row * pc.nEmbd + j] * act[pc.moeWeightOff + t * slots + k];
    }
    act[pc.outOff + t * pc.nEmbd + j] = s;
}

