===== common.glsl 1-152
// Shared binding and push-constant layout for the qwen3.8-flash-next
// kernels (LLM.md L2).
//
// Same four-arena arrangement the DiT and the text encoder use
// (dit_common.glsl): one fp32 weight arena, one fp32 activation arena, one
// fp16 activation arena and one fp16 weight bank, with "which tensor"
// expressed as an offset so that a whole block is a dispatch sequence over
// one descriptor set. vk.DispatchMultiTimed records a sequence into a single
// command buffer only if every pipeline in it was built over the same buffers
// with the same push-constant size, so the block below is one size for every
// kernel in this vertical.
//
// It is a separate file from dit_common.glsl rather than a reuse of it
// because the fields are a contract with a *shader*, and a hyper-connection
// block has no heads, no head dim and no rotary table, while it does have a
// stream count, a low rank and three activation tensors that do not exist
// anywhere else. Naming one of those `span` or `aux1` is how a graph gets
// silently wrong (the reason zimage/qwen keeps its own copy of the DiT's).

layout(binding = 0) readonly buffer Weights { float wbuf[]; };
layout(binding = 1) buffer Act { float act[]; };
layout(binding = 2) buffer HAct { float16_t hact[]; };
layout(binding = 3) readonly buffer W16 { float16_t w16[]; };
// The fp32 activation arena again, read as uints. The QSA selection is a
// bitmask — one bit per cache cell per token — and a bitmask is not a float:
// punning it through `uintBitsToFloat` would put NaN payloads in a storage
// buffer and trust them to survive, where binding the same VkBuffer at a
// second descriptor costs nothing and says what the tensor is. Every pipeline
// in this vertical declares it so that a sequence can still be recorded into
// one command buffer; only llm_attn_select.comp writes it and only
// llm_attn_wmma.comp reads it.
layout(binding = 4) buffer ActU { uint actu[]; };

// **The attention block's cache, in buffers of its own** (P18). The key and
// value planes and the indexer's raw and pooled keys used to live in the fp16
// arena above, and `maxStorageBufferRange` (4 GiB - 4) capped that arena —
// and so the context — at about 148k cells. The model is trained to 262 144.
// Each plane now has a binding of its own: at 262 144 cells over twelve layers
// the key and the value are 3.22 GB apiece and the indexer 0.81 GB, each under
// the range, and the layout reaches ~349k cells before K or V hits it.
// kOff/vOff are offsets into kcache/vcache, and ATTN_IDXRAW/idxKOff into
// icache. Only the five kernels that touch the cache use these bindings; the
// host binds them for every attention pipeline and pads 5-7 with the bank.
layout(binding = 8) buffer KCache { float16_t kcache[]; };
layout(binding = 9) buffer VCache { float16_t vcache[]; };
layout(binding = 10) buffer ICache { float16_t icache[]; };
// The quantised expert bank, read as raw words. **Only the MoE block
// declares it** (`-DMOE_QBANK`), because every other kernel in this vertical
// is built over five buffers and a shader that names a binding its descriptor
// set does not have is a pipeline that will not create.
//
// It is `uint` and not `float16_t` for the reason L5b exists: one layer's
// three expert banks are 2.52 billion weights, 5.03 GB dequantised to halves
// and 75 GB across the model, so they stay in the checkpoint's own Q4_K, Q5_K,
// Q5_1 and Q8_0 blocks and the kernel unpacks its own slab per K-step. A
// tensor is addressed by its **byte** offset here, not its element offset,
// because a Q8_0 block is 34 bytes and nothing about these formats is
// four-aligned below the row.
#ifdef MOE_QBANK
// **It is an array of buffers, one a layer.** `maxStorageBufferRange` on this
// device is 4 GiB - 4 and the whole bank is 77 GB (LLM.md L6a), so residency
// is not a matter of one arena with a per-layer offset: a layer's 1.61 GB is
// a buffer of its own, all NBANK of them are bound at one binding, and the
// layer index selects. The index is dynamically uniform — one layer per
// dispatch — so this is core Vulkan and not descriptor indexing.
#ifndef NBANK
#define NBANK 1
#endif
layout(binding = 5) readonly buffer QBank { uint w[]; } qb[NBANK];
// The same buffer again, as sixteen-byte words. A Q4_K super-block is 144
// bytes and a Q5_K one 176, both multiples of sixteen, so the 32 bytes of
// nibbles a lane unpacks per K-step are two aligned `uvec4` loads where they
// would otherwise be eight `uint` ones — and this kernel turned out to be
// bound by how many load instructions its unpack issues, not by the bytes
// they fetch. Q5_1's 24-byte and Q8_0's 34-byte blocks are not aligned to
// sixteen and go on reading the `uint` view.
layout(binding = 6) readonly buffer QBank4 { uvec4 w[]; } qb4[NBANK];
// The kernel goes on spelling them `qbank` and `qbank4`: which buffer of the
// array is the same fact for every load a dispatch issues, so it belongs at
// the declaration rather than at the 30-odd call sites.
#define qbank  qb[MOE_BANK].w
#define qbank4 qb4[MOE_BANK].w
// The **halves** arena again, as sixteen-byte words, for the grouped GEMM's
// gathered A operand (P11).
//
// `llm_moe_gemm.comp`'s MODE 0 stages BM scattered rows of the block input
// into LDS per K-step, and it was doing it one half at a time: BM*BK/LANES =
// 32 loads a lane a K-step at BM 64, each fetching **two bytes**, against the
// eight the B unpack issues for four times the data. The same reasoning that
// put the bank at binding 6 applies to the operand — this kernel is bound by
// how many load instructions it issues, not by the bytes they fetch — and a
// K-step of 32 halves is four aligned `uvec4` loads a row instead of 32
// scalar ones. The rows a gather names are the permutation's, so alignment is
// the *row stride's* to keep: `lda` and `xnOff` are both multiples of eight
// halves, which `MoEGPU.Upload` asserts rather than assumes.
layout(binding = 7) readonly buffer HAct4 { uvec4 hact4[]; };
#endif

// The **dense** weight bank read as raw words: LLM.md L8.
//
// Binding 3 above is the same buffer as halves, and for every kernel written
// before L8 that is all it is. L8's bank is not halves: a dense weight is
// staged as the checkpoint's own int8 with one fp16 scale per 32 elements of
// a row — 8.5 bits a weight against 16 — because at decode a token reads
// 8.07 GB of dense weight against the 3.67 the checkpoint ships, and that
// ratio *is* the decode rate (L7c-5). So the tiles are bytes and the scales
// are halves, in one buffer, and the buffer is bound twice: `w8` for the
// tiles and `w16` for the plane that follows them.
//
// It takes binding 5 because a dense kernel is never a MoE kernel — the two
// `#ifdef`s below are mutually exclusive and nothing declares both — and
// because every pipeline in a recorded sequence carries its own descriptor
// set, so a build that names six buffers may sit beside one that names five.
//
// **L8c-4 narrows it again and the binding does not change.** The 4.5-bit
// bank is nibble tiles plus a sixteen-byte ggml record per (column,
// super-block), so `w8` is the whole of it as raw words there too — the two
// `-D`s name which bank a build reads and both bind the same way.
#if defined(DENSE_Q8) || defined(DENSE_Q4)
layout(binding = 5) readonly buffer W8 { uint w8[]; };
#endif

// **The hyper-connection block's cross-block port** (TODO.md P22b). Every
// block owns its arenas, so an activation leaving the mixer for a sublayer
// and coming back for the combine crossed a buffer boundary through
// `llm_move.comp` — 196 dispatches a decode step, 0.54 ms of a 25 ms token,
// each of them a copy. The kernel on either side of that boundary can bind
// the *other* block's arena instead: a compute pipeline here owns its
// descriptor set, so the host builds one per (kernel, foreign buffer) pair,
// exactly as the mover did. Binding 11 is that foreign buffer; 5-10 are
// padded with the bank so the numbering stays the vertical's.
//
//   XOUT (llm_hc_cn.comp, llm_hc_combine.comp): the block output the
//   combine closes on is read from the sublayer's own fp32 arena at
//   `outOff`, and the same floats as the move copied.
//
//   XIN (llm_hc_up_gemv.comp): the mixer's output is written as halves
//   into the sublayer's fp16 A operand at `outOff`, row stride
//   HC_XIN_STRIDE, with the rows from ROWS up to HC_XIN_PADROWS zeroed —
//   `float16_t(v)` on the same fp32 value the move narrowed, so the same
//   bits. The two borrowed fields are PLE fields the mixer never uses, on
//   the SEQ_PAST rule: the mapping lives here and nothing spells them at
//   the call site.
#ifdef XOUT
layout(binding = 11) readonly buffer XOut { float xout[]; };
#endif
#ifdef XIN
layout(binding = 11) writeonly buffer XIn { float16_t xin[]; };
#define HC_XIN_STRIDE  pc.kvOff
#define HC_XIN_PADROWS pc.gatedOff
