			}
			key, val, kinds := run(k)
			if gemvSlabs(k) > 1 && !hasKind(kinds, "kv.sum") {
				t.Errorf("%d rows, %s: no reduce recorded: %v", rows, k, kinds)
			}
			for _, arm := range []struct {
				what      string
				got, want []float32
			}{{"key", key, refKey}, {"value", val, refVal}} {
